def read_file(fname):
    import os
    base = "/var/www/uploads/"
    filepath = os.path.realpath(os.path.join(base, fname))
    if not filepath.startswith(base):
        raise ValueError("Path traversal detected")
    with open(filepath, "r") as f:
        return f.read()

